t.put( 'geekoutput_nav_menu.tpl', '<header class=\'global-header\' ng-cloak> 	<nav class=\'container-fluid\'> 		<!-- Skip Navigation Link --> 		<button class="nav-skip-link sr-only sr-only-focusable btn btn-light" ng-click="layoutctrl.skipToId(\'mainbodytarget\')">Skip Navigation</button>  		<!-- Accessibility Feedback --> 		<a class="nav-skip-link sr-only sr-only-focusable btn btn-light" href="/contact">Accessibility Feedback</a>  		<div class="c-inner">  			<!-- Desktop sidebar toggler --> 			<button class=\'global-header-nav-toggle--desktop btn btn-empty global-header-icon global-header-nav-toggle\' 					ng-click="layoutctrl.localStorage.hideFixedSidebar = !layoutctrl.localStorage.hideFixedSidebar"> 				<span> 					<svg class="menu-bars" aria-hidden="true" width="14" height="13" xmlns="http://www.w3.org/2000/svg"><path d="M14 12v1H0v-1h14zm0-6v1H0V6h14zm0-6v1H0V0h14z" fill="#FFF" fill-rule="nonzero"/></svg> 					<span class="sr-only text-white">Toggle Sidebar</span> 				</span> 			</button>  			<!-- Tablet sidebar toggler --> 			<button class=\'global-header-nav-toggle--tablet btn btn-empty global-header-icon global-header-nav-toggle\' 					ng-click="layoutctrl.toggleOverlaySidebar(); $event.stopPropagation();" 					ng-class="{\'is-active\': layoutctrl.showOverlaySidebar}"> 				<span> 					<svg class="menu-bars" aria-hidden="true" width="14" height="13" xmlns="http://www.w3.org/2000/svg"><path d="M14 12v1H0v-1h14zm0-6v1H0V6h14zm0-6v1H0V0h14z" fill="#FFF" fill-rule="nonzero"/></svg> 					<span class="sr-only text-white">Toggle Sidebar</span> 				</span> 			</button>  			<!-- Mobile nav toggler --> 			<button class=\'global-header-nav-toggle--mobile btn btn-empty global-header-icon global-header-nav-toggle\' 					ng-click="navctrl.menuVars.mobilenav=!navctrl.menuVars.mobilenav; searchctrl.searchfocus=false;" 					ng-class="{ \'is-active\': navctrl.menuVars.mobilenav }"> 				<span> 					<svg class="menu-bars" aria-hidden="true" width="14" height="13" xmlns="http://www.w3.org/2000/svg"><path d="M14 12v1H0v-1h14zm0-6v1H0V6h14zm0-6v1H0V0h14z" fill="#FFF" fill-rule="nonzero"/></svg> 					<span class="sr-only text-white">Show Menu</span> 				</span> 			</button>  			<div class=\'global-header-logo\' ng-include="\'geekoutput_header_logo.tpl\'"></div>  			<div class=\'global-header-nav\' ng-class="{ \'logged-in\': navctrl.currentUser.userid }"> 				<div class=\'global-header-nav-inner\' 					ng-controller="GeekSearch as searchctrl" 					ng-class="{ \'is-searching\': searchctrl.searchfocus && !navctrl.menuVars.mobilenav, \'has-mobile-nav\': navctrl.menuVars.mobilenav && !searchctrl.searchfocus }" 					click-out="searchctrl.unfocus()"> 					<button class=\'global-header-nav-primary-mobile-toggler btn btn-indigo\' ng-click="navctrl.menuVars.mobilenav=false"> 						<i class="fa-solid fa-xmark"></i> 						<span class="sr-only text-white">Close Menu</span> 					</button> 					<div class=\'global-header-nav-primary-wrapper\'>  						<!-- Mobile Nav Title --> 						<span class="visible-xs global-secondary-nav-section-header"> 							BoardGameGeek 						</span>  						<!-- Primary Nav --> 						<ul class=\'global-header-nav-primary\'> 							<main-menu-dropdown 								dropdown=\'dropdown\' 								ng-repeat=\'dropdown in ::navctrl.menu\' 								active-submenu=\'navctrl.menuVars.activeSubmenu\'></main-menu-dropdown>  							<li ng-if="navctrl.loaded && !navctrl.currentUser.userid" 								class=\'global-header-nav-session global-header-nav-primary-separated hidden-xs\'> 								<button class=\'btn btn-sm\' type=\'button\' login-required>Sign In</button> 							</li> 							<li ng-if="navctrl.loaded && !navctrl.currentUser.userid" class=\'global-header-nav-session hidden-xs\'> 								<a class=\'btn btn-sm\' href="/join">Join (it\'s free)!</a> 							</li> 							<li ng-if="navctrl.loaded && navctrl.currentUser.userid" 								class="global-header-nav-user-notifications global-header-nav-primary-separated hidden-xs"> 								<span ng-if="navctrl.currentUser.showdashboardicon && navctrl.domain == \'boardgame\'"> 									<a class="global-header-icon" href="/dashboard" uib-tooltip="Dashboard" tooltip-placement="bottom" tooltip-popup-delay="500"> 										<i class="fa-solid fa-gauge-high"></i> 										<span class="sr-only text-white">Dashboard</span> 									</a> 								</span> 								<geekmail-notifications></geekmail-notifications> 								<subscription-notifications></subscription-notifications> 							</li> 						</ul>  						<geekoutput-sidebar></geekoutput-sidebar> 					</div>  					<!-- MOBILE ONLY --> 					<div class=\'global-header-nav-mobile-links\'>  						<!-- Sign Up / Sign In --> 						<ul class=\'global-header-nav-primary\'> 							<li ng-if="navctrl.loaded && !navctrl.currentUser.userid" 								class=\'global-header-nav-session global-header-nav-primary-separated\'> 								<button class=\'btn btn-sm\' type=\'button\' login-required>Sign In</button> 							</li> 							<li ng-if="navctrl.loaded && !navctrl.currentUser.userid" class=\'global-header-nav-session\'> 								<a class=\'btn btn-sm\' href="/join">Join (it\'s free)!</a> 							</li> 						</ul>  						<!-- Dashboard Link --> 						<span ng-if="navctrl.currentUser.showdashboardicon"> 							<a class="global-header-icon" href="/dashboard" uib-tooltip="Dashboard" tooltip-placement="bottom" tooltip-popup-delay="500"> 								<i class="fa-solid fa-gauge-high"></i> 								<span class="sr-only text-white">Dashboard</span> 							</a> 						</span>  						<!-- Geekmail / Subscriptions --> 						<geekmail-notifications></geekmail-notifications> 						<subscription-notifications></subscription-notifications>  						<!-- Search --> 						<button class=\'btn btn-empty global-header-icon mobile-search-toggle\' 								ng-click="searchctrl.searchfocus=true; searchctrl.activateSearch(); navctrl.menuVars.mobilenav=false"> 							<i class="fa-solid fa-flip-horizontal fa-magnifying-glass"></i> 							<span class="sr-only bg-primary">Search</span> 						</button> 					</div>  					<!-- Search --> 					<div class=\'global-header-nav-search\'> 						<div class="global-header-nav-search-backdrop" 							ng-click="searchctrl.searchfocus=false"></div> 						<form class="global-header-nav-search-inner"> 							<div class=\'form-group-search\'> 								<label class=\'sr-only text-white\' for="site-search">Search Site</label> 								<input class=\'form-control\' 										id="site-search" 										ng-model=\'searchctrl.search.q\' 										type=\'text\' 										autocorrect=\'off\' 										autocomplete="off" 										placeholder=\'Search\' 										ng-focus="searchctrl.searchfocus=true;" 										focus-on="searchActivated" 										ng-keypress="searchctrl.searchOnEnter($event)" 										typeahead-focus-first="false" 										uib-typeahead="item as item.name for item in searchctrl.jsonSearch($viewValue)" 										typeahead-on-select="searchctrl.goToItem($item)" 										typeahead-wait-ms="500" 										typeahead-always-search-on-focus="true" 										typeahead-template-url="geekoutput_search_template.tpl" 										typeahead-no-results="searchctrl.searchEmpty" 										typeahead-loading="searchctrl.searchLoading" 									> 								<button class=\'search\' type=\'submit\' ng-click="searchctrl.fullSearch()"> 									<i class="fs-sm fa-solid fa-magnifying-glass"></i> 									<span class="sr-only bg-primary">Search</span> 								</button>  								<i class="fi-refresh is-refreshing" ng-show="searchctrl.searchLoading"></i>  								<button class="search-clear" type="reset" ng-show="searchctrl.search.q" ng-click="searchctrl.search.q = \'\'"> 									<i class="fs-sm fa-solid fa-xmark"></i> 									<span class="sr-only">Clear Search</span> 								</button> 							</div> 						</form> 						<div class="global-header-nav-search-advanced" 							ng-show="searchctrl.searchfocus" ng-cloak> 							<select class="search-select" ng-model="searchctrl.search.objecttype" ng-change="searchctrl.activateSearch()"> 								<option ng-repeat="searchOption in searchctrl.searchOptions" value="{{searchOption.objecttype}}">{{searchOption.name}}</option> 							</select> 							<a class="advanced-search-link" ng-if="searchctrl.search.q === \'\'" ng-href="{{navctrl.advSearchUrl}}">Advanced Search</a> 						</div> 					</div>   					<!-- User Profile --> 					<div uib-dropdown 						ng-if="navctrl.loaded && navctrl.currentUser.userid" 						keyboard-nav="true" 						is-open="navctrl.menuVars.activeSubmenu == \'user\'" 						class=\'avatar-dropdown global-header-nav-user\'>  						<button class=\'btn btn-sm btn-empty avatar-dropdown__btn\' uib-dropdown-toggle type=\'button\'> 							<avatar-md unlinked="true" class="avatar-dropdown__avatar" user="navctrl.currentUser.user"></avatar-md> 							<span class="sr-only">Profile Menu</span> 							<span class=\'caret\'></span> 						</button>  						<div uib-dropdown-menu class=\'avatar-dropdown__menu dropdown-menu dropdown-menu-right dropdown-menu-xl container-fluid\'>   							<!-- Profile Link --> 							<a class="avatar-dropdown__profile-link link-text-color" ng-href=\'/profile/{{navctrl.currentUser.username}}\'> 								<avatar-md unlinked="true" class="avatar-dropdown__avatar" user="navctrl.currentUser.user"></avatar-md> 								<div class="avatar-dropdown__profile-link-text"> 									<span class="text-bold fs-sm avatar-dropdown__profile-title">View Profile</span> 									<span class="text-muted avatar-dropdown__profile-link-username">&#64;{{navctrl.currentUser.username}} 									</span> 								</div> 							</a>  							<!-- Secondary Link Grid --> 							<div class="avatar-dropdown__link-grid"> 								<ul> 									<li><a href=\'/collection/user/{{navctrl.currentUser.username}}\'>Collection</a></li> 									<li><a href=\'/plays/bymonth/user/{{navctrl.currentUser.username}}/subtype/boardgame\'>Logged 											Plays</a></li> 									<li><a href=\'/tags/user/{{navctrl.currentUser.username}}\'>Tags</a></li> 									<li><a href=\'/subscriptions\'>Subscriptions</a></li> 									<li><a href=\'/trade\'>Trades</a></li> 									<li><a href=\'/market/dashboard\'>GeekMarket</a></li> 									<li><a href="/fan/user/{{navctrl.currentUser.username}}?subtype=boardgame">Fan Items</a></li> 									<li ng-if="navctrl.currentUser.admin.login && !navctrl.currentUser.admin.any"> 										<a href=\'/geekadmin.php?action=adminlogin\'>Admin Login</a> 									</li> 								</ul> 								<ul> 									<li><a href=\'/wishlist/{{navctrl.currentUser.username}}\'>Wishlist</a></li> 									<li><a href=\'/profile/{{navctrl.currentUser.username}}/guilds\'>Guilds</a></li> 									<li><a href=\'/images/user/{{navctrl.currentUser.userid}}/{{navctrl.currentUser.username}}\'>Gallery</a></li> 									<li><a href=\'/geekbuddy.php\'>GeekBuddies</a></li> 									<li><a href=\'/geeklist/mylists\'>Geeklists</a></li> 									<li><a href=\'/blogs/myblogs\'>Blogs</a></li> 									<li><a href=\'/geekexchange/myexchanges\'>GeekExchanges</a></li> 								</ul> 							</div>  							<!-- Admin Menu --> 							<div show-access="seemenus" class="admin-menu"> 								<div class=\'admin-menu__title dropdown-header\'> 									<i class="fa-solid fa-shield-halved text-muted"></i> Admin Menu 								</div> 								<div show-access="admin_login" class="avatar-dropdown__link-grid"> 									<ul> 										<li show-access="any"><a href="/geekadmin.php?action=adminlogout">Admin Logout</a></li> 										<li show-access="userperm"><a href="/geekaccount/bulkedituserpriv">Edit Users\' Privs</a></li> 										<li show-access="admin"><a href="/thumbswatch.php">Rules Violation Reports</a></li> 										<li show-access="ebaymgr"><a href="/geekbay.php?action=viewreports">Ebay Problem Reports</a></li> 										<li show-access="itemmgr"><a href="/geekadmin.php?action=specialsearches">Special Searches</a></li> 										<li show-access="seemenus"><a href=\'/amazon/search/thing/next/views\'>Link Amazon</a></li> 										<li show-access="seemenus"><a href=\'/forums/region/42\'>Geekdo Forums</a></li> 										<li show-access="admin"><a href=\'/browseadmins\'>Browse Admins</a></li> 										<li show-access="userdel"><a href=\'/geekadmin/blockedemaildomains\'>Blocked Email Domains</a></li> 									</ul> 									<ul> 										<li show-access="admin_loggedout"><a href="/geekadmin.php?action=adminlogin">Admin Login</a></li> 										<li show-access="usermgr"><a href="/geekadmin.php?action=viewdeleted">Deleted Users</a></li> 										<li show-access="seemenus"><a href="/wiki/page/Admin:Main_Page">Admin Wiki</a></li> 										<li show-access="admin"><a href="/geekadmin.php?action=viewblockedips">IP Blocking</a></li> 										<li show-access="ebaymgr"><a href="/geekbay.php?action=viewuser">Ebay View User</a></li> 										<li show-access="giftmgr"><a href="/geekgold/bulktransfer">Bulk Transfer GeekGold</a></li> 										<li show-access="seemenus"><a href=\'/amazon/errors/us\'>Amazon Errors</a></li> 										<li show-access="massmail"><a href=\'/newsletter/create\'>Send Newsletter</a></li> 									</ul> 								</div>  								<div show-access="superadmin"> 									<div class=\'col-xs-12\'> 										<div class=\'admin-menu__title-secondary dropdown-header\'>Domains</div> 									</div> 									<div class="avatar-dropdown__link-grid"> 										<ul class="row"> 											<li><a href="/?domain_override=boardgame">BGG Override</a></li> 											<li><a href="/?domain_override=videogame">VGG Override</a></li> 										</ul> 										<ul class="row"> 											<li><a href="/?domain_override=rpg">RPGG Override</a></li> 										</ul> 									</div> 								</div> 							</div>  							<!-- Settings --> 							<a class="avatar-dropdown__icon-cta link-text-color" href="/settings"> 								<i class="fa-solid fa-cog"></i> 								Settings 							</a>  							<!-- Sign Out --> 							<a class="avatar-dropdown__icon-cta link-text-color" href="/logout"> 								<i class="fa-solid fa-arrow-right-to-bracket"></i> 								Sign Out 							</a> 						</div> 					</div> 				</div> 			</div> 		</div> 	</nav> </header>  ' );
t.put( 'geekoutput_nav_menu_dropdown.html', '<li uib-dropdown 	 keyboard-nav="true" 	 is-open="activeSubmenu == dropdown.id">  	<button class=\'btn btn-sm\' uib-dropdown-toggle type=\'button\'> 		{{dropdown.name}} <span class=\'caret hidden-sm hidden-xs\'></span> 	</button> 	<div uib-dropdown-menu class=\'dropdown-menu\' 		  ng-class="{\'dropdown-menu-xl\': dropdown.wide, \'container-fluid\': dropdown.wide}"> 		<div show-access="{{section.requireAccess}}" ng-repeat="section in dropdown.sections"> 			<div ng-if=\'section.header\' class=\'col-xs-12\'> 				<div class=\'dropdown-header\'>{{section.header}}</div> 			</div> 			<ul ng-repeat="list in section.lists" ng-class="{ \'col-xs-6 col-sm-12 col-md-6\': section.lists.length > 1 }"> 				<li ng-repeat="link in list.links"><a ng-href=\'{{link.href}}\'>{{link.anchor}}</a></li> 			</ul> 	</div> </li>  ' );
t.put( 'geekoutput_modal_confirm.tpl', '<div class="modal-header"> 	<h3 class="modal-title">{{confirmTitle ||"Your Changes"}}</h3> </div> <div class="modal-body"> 	{{confirmBody || "Your changes have not been saved."}} </div> <div class="modal-footer"> 	<button class="btn btn-danger" type="button" ng-click="$close()">{{confirmClose || "Discard"}}</button> 	<button class="btn btn-default" type="button" ng-click="$dismiss()">{{confirmDismiss || "Continue Editing"}}</button> </div>  ' );
t.put( 'geekoutput_dialog_feedback.tpl', '	<div class=\'modal-header modal-header-table\'> 		<div class=\'modal-header-table-left\'> 		</div>  		<div class=\'modal-header-table-center\'> 			<h4 class=\'modal-title\'>Feedback</h4> 		</div>  		<div class=\'modal-header-table-right\'> 			<button class=\'close\' type=\'button\' ng-click="$dismiss()"> 				<span>×</span> 			</button> 		</div> 	</div> 	<div class=\'modal-body container-fluid\'> 		<div class=\'form-group\'> 			Let us know what you think! If you are able to send screenshots, please send to 			<a href="mailto:developers@geekdo.com">developers@geekdo.com</a> 		</div>  		<div class="row"> 			<div class="col-xs-12"> 				<form name="form"> 					<div class="form-group" ng-class="{ \'has-error\': errors.subject}"> 						<label for="subject">Subject</label> 						<input id="subject" 								 name="subject" 								 class="form-control" 								 type="text" 								 ng-model="feedback.subject" 								 placeholder="I love the new design!"> 					</div> 					<div class="form-group" ng-class="{ \'has-error\': errors.body}"> 						<label for="feedback_body">Description</label> 						<textarea id="feedback_body" 							 style=\'height: 200px\' 							 msd-elastic 							 name="body" 							 class="form-control" 							 ng-model="feedback.body"></textarea> 					</div> 				</form> 			</div> 		</div> 	</div> 	<div class=\'modal-footer\'> 		<button class=\'btn btn-primary\' type=\'button\' ng-click="save()">Send</button> 		<button class=\'btn btn-default\' ng-click="$dismiss()">Cancel</button> 	</div>  ' );
t.put( 'geekoutput_recentlyviewed.tpl', '<ul class=\'global-secondary-nav-links\'> 	<li ng-repeat="item in ::recentctrl.data.items" ng-bind-html="::item.url|to_trusted"></li> 	<li><a href="/geektracker/browse">See All &raquo;</a></li> </ul> ' );
t.put( 'geekoutput_plea.tpl', '<div class=\'support-banner\' ng-class="{\'support-banner-minimized\': !$ctrl.showThermometer, \'last-days\': $ctrl.lastDays}" ng-if="!$ctrl.loadingOrNotInFundraiserPeriod" data-nosnippet> 	<button ng-show="$ctrl.showThermometer" class=\'support-banner-toggle-button\' ng-click="$ctrl.toggleAppeal();" attr.aria-expanded="{{$ctrl.showThermometer}}"> 		<span class="sr-only">Minimize</span> 		<i class="fa fa-minus"></i> 	</button>  	<button  ng-show="!$ctrl.showThermometer" class=\'support-banner-toggle-button\' ng-click="$ctrl.toggleAppeal();" attr.aria-expanded="{{$ctrl.showThermometer}}"> 		<span class="sr-only">Expand</span> 		<i class="fa fa-plus"></i> 	</button>  	<!-- Background Banner Image --> 	<div class=\'support-banner-banner-bg\'></div>  	<!-- Left Container --> 	<div class=\'support-banner-left\'> 		<!-- Header Section --> 		<div class=\'support-banner-header\'> 			<div class=\'support-banner-text\'> 				<h2 ng-if="!$ctrl.yearComplete" class=\'support-banner-title\'> 					{{$ctrl.plea.pleaText.title}} 				</h2> 				<p ng-if="!$ctrl.yearComplete" class=\'support-banner-subtitle\'> 					{{$ctrl.plea.pleaText.preTimeLeftText}} <a href="/support" style="white-space: nowrap;">Learn More</a> 				</p>  				<!-- Support Button (shown when minimized) --> 				<a ng-if="!$ctrl.yearComplete" href="/support#supportForm" class="support-banner-btn" style="margin-top: 8px"> 					<i class="fa fa-bolt"></i> 					Support BGG this Year 				</a>  				<h2 ng-if="$ctrl.yearComplete" class=\'support-banner-title\'> 					{{ $ctrl.supportYear }} Support drive complete! 				</h2> 				<p ng-if="$ctrl.yearComplete" class=\'support-banner-subtitle\'> 					Thank you for your generous support! 				</p> 			</div>  			<!-- Progress Container (hidden when minimized) --> 			<div class=\'support-banner-progress-container\' ng-hide="!$ctrl.showThermometer" ng-if="$ctrl.plea"> 				<!-- Progress Meta --> 				<div class=\'support-banner-progress-meta\'> 					<p> 						Supporters 						<span>{{$ctrl.plea.thermometer.numsupporters|number}} / 20,000</span> 					</p> 					<div class=\'support-banner-progress-time\'> 						<p ng-if="!$ctrl.yearComplete">{{$ctrl.daysLeft}} {{$ctrl.daysLeft === 1 ? \'day\' : \'days\'}} Left</p> 					</div> 				</div>  				<!-- Progress Bar --> 				<div class=\'support-banner-progress-bar\' role="progressbar" attr.aria-valuenow="{{$ctrl.plea.thermometer.percentage}}" aria-valuemin="0" aria-valuemax="100" attr.aria-label="Support drive {{$ctrl.plea.thermometer.percentage}}% funded"> 					<div class=\'support-banner-progress-fill\' ng-style="{\'width\': $ctrl.plea.thermometer.widthStyle }"></div> 					<div 						class=\'support-banner-milestone\' 						ng-repeat="milestone in $ctrl.milestones track by $index" 						ng-class="{ 						\'support-banner-milestone--passed\': $ctrl.plea.thermometer.numsupporters / $ctrl.plea.thermometer.goal >=                   ($index + 1) / $ctrl.milestones.length                   }" 						ng-style="{\'left\': ((($index + 1) / $ctrl.milestones.length) * 100).toString() + \'%\'}"> 						<div class=\'support-banner-tooltip\' 							 ng-if="$ctrl.plea.thermometer.numsupporters / $ctrl.plea.thermometer.goal >=                   ($index + 1) / $ctrl.milestones.length"> 							<div class=\'support-banner-tooltip-content\'> 								<p>{{ milestone.title }}</p> 								<p>{{ milestone.body }}</p> 							</div> 						</div> 					</div> 				</div>   				<!-- Progress Footer --> 				<div class=\'support-banner-progress-footer\'> 					<p>Supporter Badge + 1000 GeekGold at year\'s end ($15 minimum)</p> 					<p>{{$ctrl.plea.thermometer.percentage | number:0}}% Funded</p> 				</div> 			</div>  			<div class="bgg-pattern bgg-pattern--left"></div> 			<div class="bgg-pattern"></div> 		</div> 	</div>  	<!-- Right Container - Testimonial --> 	<div class=\'support-banner-right\'> 		<div ng-if="$ctrl.plea.blurb && $ctrl.plea.user" style="width: 100%"> 			<!-- Avatar Background --> 			<div class="support-banner-avatar-tint"></div> 			<div class=\'support-banner-avatar-bg\' ng-if="$ctrl.plea.user.avatar"> 				<avatar-default user="$ctrl.plea.user" size="mdstatic"></avatar-default> 			</div>  			<!-- Testimonial Card --> 			<div class=\'support-banner-testimonial-card\'> 				<avatar-default user="$ctrl.plea.user" ng-if="$ctrl.plea.user.avatar" size="default"></avatar-default> 				<div class=\'support-banner-testimonial-content\'> 					<p class=\'support-banner-user-quote\'> 						&quot;{{$ctrl.plea.blurb}}&quot; 					</p> 					<p class=\'support-banner-user-pick\' ng-if="$ctrl.plea.favorite"> 						<span>Game Pick &ndash; </span> 						<a ng-href="{{$ctrl.plea.favorite.href}}">{{$ctrl.plea.favorite.name}}</a> 					</p> 					<!-- User Badge --> 					<a class=\'support-banner-user-badge\' ng-href="{{$ctrl.plea.user.href}}"> 						<span class="dash">&ndash;</span> 						<p ng-if="$ctrl.plea.user.firstname && $ctrl.plea.user.lastname"> 							{{$ctrl.plea.user.firstname}} {{$ctrl.plea.user.lastname}} 						</p> 						<span class="divider" ng-if="$ctrl.plea.user.firstname && $ctrl.plea.user.lastname"></span> 						<p>&#64;{{$ctrl.plea.user.username}}</p> 					</a> 				</div> 			</div> 		</div>  		<div ng-if="$ctrl.plea.blurb && !$ctrl.plea.user" style="width: 100%"> 			<!-- Testimonial Card --> 			<div class=\'support-banner-testimonial-card\'> 				<div class=\'support-banner-testimonial-content\'> 					<p class=\'support-banner-user-quote\'>&quot;{{$ctrl.plea.blurb}}&quot;</p> 					<!-- User Badge --> 					<div class=\'support-banner-user-badge\'> 						<span class="dash">&ndash;</span> 						<p>A Geek</p> 					</div> 				</div> 			</div> 		</div>  		<!-- Support Button --> 		<a href="/support#supportForm" class="support-banner-btn"> 			<i class="fa fa-bolt"></i> 			Support BGG this Year 		</a> 	</div> </div>  ' );
t.put( 'geekoutput_plea_modal_loggedout.tpl', '	<div class="modal-header"> 		<h3 class="modal-title">Heads up!</h3> 	</div> 	<div class="modal-body"> 		 If you want your fundraiser support linked to your account, you should <button login-required class="btn btn-link">log in</button> first! 	</div> 	<div class="modal-footer"> 		<button class="btn btn-primary" type="button" ng-click="$close()">Support</button> 		<button class="btn btn-default" type="button" ng-click="$dismiss()">Cancel</button> 	</div> ' );
t.put( 'geekoutput_module_hotness.tpl', '<div class=\'global-secondary-nav-section-actions\'> 	<persistent-selector 		ng-show="hotctrl.params.objecttype === \'thing\'" 		default="thumbnails" 		template-url="geekoutput_hotness_density_selector.html" 		key="hotnessDensity" 		value="hotctrl.density"> 	</persistent-selector> 	<span uib-dropdown> 		<button type=\'button\' class=\'btn btn-xs btn-text-link\' uib-dropdown-toggle> 			{{hotctrl.hotnessTypes | fieldFromArrayById: \'objecttype\': hotctrl.params.objecttype: \'label\'}} <span class=\'caret\'></span> 		</button> 		<ul uib-dropdown-menu> 			<li ng-repeat="hotnessType in hotctrl.hotnessTypes"> 				<button class=\'btn btn-empty\' type=\'button\' ng-click="hotctrl.setObjecttype( hotnessType.objecttype )"> 					{{hotnessType.label}} 				</button> 			</li> 		</ul> 	</span> </div> <ul class=\'global-secondary-nav-links hotness\'> 	<li class=\'hotness-item\' ng-class="{\'has-image\': item.imageurl && hotctrl.density === \'thumbnails\' }" 		 ng-repeat="item in hotctrl.data.items|limitTo:(hotctrl.density === \'thumbnails\' && hotctrl.params.objecttype === \'thing\' && 15) || 30"> 		<a ng-href="{{::item.href}}"> 			<div class=\'hotness-item-image\' ng-if="hotctrl.density === \'thumbnails\'"> 				<span ng-if="::item.imageurl"> 					<img ng-src="{{::item.images.square30.src}}" 						  ng-srcset="{{::item.images.square30.src}} 1x, {{::item.images.square30[\'src@2x\']}} 2x" 						  alt="{{::item.name}} game" 						  width="30" 						  height="30" 						  loading="lazy" 						  role="presentation" 						  > 				</span> 				<span class=\'hotness-item-image-placeholder\' ng-if="!item.imageurl"> 					<i class=\'fi-photo\'></i> 				</span> 			</div> 			<div class=\'hotness-item-body\'> 				<div class=\'hotness-item-title\'> 					{{::item.name | characters: 30}} 				</div> 				<div class=\'hotness-item-meta\' 					  ng-show="(item.yearpublished) && hotctrl.density === \'thumbnails\'"> 					  <span class="sr-only">Published </span> 					{{::item.yearpublished}} 				</div> 			</div>  			<div class=\'hotness-item-delta delta\' ng-class="{ \'delta-lg\': item.delta > 5, \'delta-xl\': item.delta > 10 }"> 				<span ng-show="::item.delta < 0" 					   class="c-is-negative" 						title="Since yesterday: {{::item.delta}}"> 					<span class="glyphicon glyphicon-triangle-bottom"></span> 				</span> 				<span ng-show="::item.delta > 0" 						class="c-is-positive" 						title="Since yesterday: +{{::item.delta}}"> 					<span class="glyphicon glyphicon-triangle-top"></span> 				</span> 				<span ng-show="::item.delta == 0" 						title="Unchanged since yesterday"> 					<span class="glyphicon glyphicon-minus"></span> 				</span> 				<span ng-show="::item.delta === null" 						title="New to The Hotness today"> 					{{::item.delta}} 					<span class=\'delta-new\'></span> 				</span> 			</div> 		</a> 	</li> </ul>  ' );
t.put( 'geekoutput_hotness_density_selector.html', '<span uib-dropdown class=\'pull-right\'> 	<button type=\'button\' uib-tooltip=\'Display options\' tooltip-popup-delay=\'500\' tooltip-append-to-body=\'true\' tooltip-placement=\'left\' class=\'btn btn-xs btn-muted-link c-icon\' uib-dropdown-toggle> 		<span class="sr-only text-muted">Change hotness display style</span>     <span class=\'glyphicon glyphicon-option-vertical\'></span> 	</button> 	<ul uib-dropdown-menu> 		<li class=\'dropdown-header\'> 			Hotness Display 		</li> 		<li class=\'dropdown-option\' ng-class="{active: value === \'thumbnails\'}"> 			<button class=\'btn btn-empty\' type=\'button\' ng-click="value = \'thumbnails\'"> 				<span class="sr-only">Stats and </span>Thumbnails 			</button> 		</li> 		<li class=\'dropdown-option\' ng-class="{active: value === \'list\'}"> 			<button class=\'btn btn-empty\' type=\'button\' ng-click="value = \'list\'"> 				List 			</button> 		</li> 	</ul> </span>  ' );
